  1982  int check_nthreads(blosc2_context* context) {
  1983    if (context->nthreads <= 0) {
  1984      BLOSC_TRACE_ERROR("nthreads must be a positive integer.");
  1985      return BLOSC2_ERROR_INVALID_PARAM;
  1986    }
  1987
  1988    if (context->new_nthreads != context->nthreads) {
  1989      if (context->nthreads > 1) {
  1990        release_threadpool(context);
  1991      }
  1992      context->nthreads = context->new_nthreads;
  1993    }
  1994    if (context->new_nthreads > 1 && context->threads_started == 0) {
  1995      init_threadpool(context);
  1996    }
  1997
  1998    return context->nthreads;
  1999  }
