  2001  /* Do the compression or decompression of the buffer depending on the
  2002     global params. */
  2003  static int do_job(blosc2_context* context) {
  2004    int32_t ntbytes;
  2005
  2006    /* Set sentinels */
  2007    context->dref_not_init = 1;
  2008
  2009    /* Check whether we need to restart threads */
  2010    check_nthreads(context);
  2011
  2012    /* Run the serial version when nthreads is 1 or when the buffers are
  2013       not larger than blocksize */
  2014    if (context->nthreads == 1 || (context->sourcesize / context->blocksize) <= 1) {
  2015      /* The context for this 'thread' has no been initialized yet */
  2016      if (context->serial_context == NULL) {
  2017        context->serial_context = create_thread_context(context, 0);
  2018      }
  2019      else if (context->blocksize != context->serial_context->tmp_blocksize) {
  2020        free_thread_context(context->serial_context);
  2021        context->serial_context = create_thread_context(context, 0);
  2022      }
  2023      BLOSC_ERROR_NULL(context->serial_context, BLOSC2_ERROR_THREAD_CREATE);
  2024      ntbytes = serial_blosc(context->serial_context);
  2025    }
  2026    else {
  2027      ntbytes = parallel_blosc(context);
  2028    }
  2029
  2030    return ntbytes;
  2031  }
