  2308      // When splitting, the number of streams is computed differently
  2309      if (context->leftover) {
  2310        nstreams = (context->nblocks - 1) * context->typesize + 1;
  2311      }
  2312      else {
  2313        nstreams *= context->typesize;
  2314      }
  2315    }
