  2317    if (memcpyed) {
  2318      if (context->sourcesize + context->header_overhead > context->destsize) {
  2319        /* We are exceeding maximum output size */
  2320        ntbytes = 0;
  2321      }
  2322      else {
  2323        context->output_bytes = context->header_overhead;
  2324        ntbytes = do_job(context);
  2325        if (ntbytes < 0) {
  2326          return ntbytes;
  2327        }
