  2329        context->dest[BLOSC2_CHUNK_FLAGS] = context->header_flags;
  2330        // and clear the memcpy bit in context (for next reuse)
  2331        context->header_flags &= ~(uint8_t)BLOSC_MEMCPYED;
  2332      }
  2333    }
